<script lang="ts">
  import { onMount } from 'svelte';
  import type { CmsClient } from '../../services/cms/client';
  import { createCmsClient } from '../../services/cms/client';
  import type { CmsConnection, CmsDocument, CmsKind, CmsProfile, CmsSettings } from '../../features/cms/types';
  import { canAdmin, canEdit, cmsKindLabels } from '../../features/cms/types';
  import CmsAccount from './CmsAccount.svelte';
  import CmsDocumentList from './CmsDocumentList.svelte';
  import CmsEditor from './CmsEditor.svelte';
  import CmsMediaLibrary from './CmsMediaLibrary.svelte';
  import SettingsPanel from './CmsSettings.svelte';
  import CmsMembers from './CmsMembers.svelte';

  export let connection: CmsConnection;
  export let defaults: CmsSettings;
  export let initialView = 'overview';
  const client: CmsClient = createCmsClient(connection);
  type View = 'overview' | 'content' | 'editor' | 'media' | 'settings' | 'members' | 'audit' | 'backup';
  let view: View = (['overview','content','editor','media','settings','members','audit','backup'].includes(initialView) ? initialView : 'overview') as View;
  let profile: CmsProfile | null = null; let documents: CmsDocument[] = []; let loading = true; let error = ''; let message = ''; let selected: CmsDocument | null = null; let newKind: CmsKind = 'post'; let busyId = ''; let auditEntries: Array<Record<string, unknown>> = []; let auditLoading = false; let backupBusy = ''; let editorDirty = false; let settingsDirty = false; let authChangeGuard = false; let importInput: HTMLInputElement;
  const navigation: Array<{ id: View; label: string; needs?: 'edit' | 'admin' }> = [{ id:'overview',label:'总览' },{ id:'content',label:'内容',needs:'edit' },{ id:'editor',label:'编辑器',needs:'edit' },{ id:'media',label:'图片',needs:'edit' },{ id:'settings',label:'设置',needs:'admin' },{ id:'members',label:'成员',needs:'admin' },{ id:'audit',label:'审计',needs:'admin' },{ id:'backup',label:'备份',needs:'edit' }];
  $: editable = canEdit(profile); $: admin = canAdmin(profile); $: visibleNav = navigation.filter((item) => !item.needs || item.needs === 'edit' && editable || item.needs === 'admin' && admin); $: currentPublished = documents.filter((document) => document.status === 'published').length; $: currentDrafts = documents.filter((document) => document.status === 'draft').length;
  async function loadWorkspace(initial = false, useRequestedDocument = false) { if (initial) loading = true; error = ''; try { const nextProfile = await client.profile(); profile = nextProfile; documents = nextProfile && canEdit(nextProfile) ? await client.documents() : []; if (useRequestedDocument) { const requestedId = new URLSearchParams(window.location.search).get('id'); const requested = requestedId ? documents.find((item) => item.id === requestedId) : null; if (requested) { selected = requested; newKind = requested.kind; view = 'editor'; } } } catch (cause) { error = cause instanceof Error ? cause.message : '后台连接失败，请检查网络或登录状态。'; } finally { if (initial) loading = false; } }
  async function handleAuthChange() { try { const nextProfile = await client.profile(); if (nextProfile?.user_id === profile?.user_id) { profile = nextProfile; return; } if (editorDirty || settingsDirty) { authChangeGuard = true; message = '登录账户已改变。为保护未保存内容，当前页面未自动重置；请先保存或导出文本后再刷新。'; return; } profile = nextProfile; documents = nextProfile && canEdit(nextProfile) ? await client.documents() : []; selected = null; editorDirty = false; settingsDirty = false; } catch (cause) { error = cause instanceof Error ? cause.message : '账户状态更新失败'; } }
  function allowLeave(next: View) { if (next === view) return true; const changed = view === 'editor' ? editorDirty : view === 'settings' ? settingsDirty : false; return !changed || confirm('当前页面有未保存修改，确定离开吗？'); }
  function setView(next: View): boolean { if (!allowLeave(next)) return false; if ((next === 'content' || next === 'editor' || next === 'media' || next === 'backup') && !editable) { message = '当前账户没有内容编辑权限。'; return false; } if ((next === 'settings' || next === 'members' || next === 'audit') && !admin) { message = '当前账户没有管理权限。'; return false; } editorDirty = false; settingsDirty = false; view = next; window.history.replaceState(null, '', `/admin/?view=${next}`); if (next === 'audit') loadAudit(); return true; }
  function openDocument(document: CmsDocument) { if (!setView('editor')) return; selected = document; newKind = document.kind; }
  function create(kind: CmsKind) { if (!setView('editor')) return; selected = null; newKind = kind; }
  function upsert(document: CmsDocument) { documents = [document, ...documents.filter((item) => item.id !== document.id)].sort((a,b) => b.updated_at.localeCompare(a.updated_at)); selected = document; }
  async function action(document: CmsDocument, action: 'publish' | 'unpublish' | 'trash' | 'restore') { busyId = document.id; error = ''; try { const updated = await client.action(document, action); upsert(updated); message = action === 'publish' ? '内容已发布。' : action === 'unpublish' ? '内容已撤回。' : action === 'trash' ? '内容已移入回收站。' : '内容已恢复为草稿。'; } catch (cause) { error = cause instanceof Error ? cause.message : '操作失败'; } finally { busyId = ''; } }
  async function loadAudit() { if (!admin) return; auditLoading = true; try { auditEntries = await client.audit() as Array<Record<string, unknown>>; } catch (cause) { error = cause instanceof Error ? cause.message : '审计记录读取失败'; } finally { auditLoading = false; } }
  async function downloadBackup(format: 'json' | 'markdown') { backupBusy = format; error = ''; try { const backup = await client.backup(format); const blob = new Blob([backup.content], { type: backup.mime }); const url = URL.createObjectURL(blob); const link = window.document.createElement('a'); link.href = url; link.download = backup.filename; link.click(); URL.revokeObjectURL(url); message = '导出内容备份已下载。'; } catch (cause) { error = cause instanceof Error ? cause.message : '导出失败，请检查登录和权限。'; } finally { backupBusy = ''; } }
  async function importBackup(event: Event) { const file = (event.currentTarget as HTMLInputElement).files?.[0]; if (!file) return; backupBusy = 'import'; error = ''; try { const data: unknown = JSON.parse(await file.text()); const result = await client.importContent(data); await loadWorkspace(false, false); message = `内容导入完成：新增 ${result.imported} 条，重复跳过 ${result.skipped} 条。`; } catch (cause) { error = cause instanceof Error ? cause.message : '导入失败，请选择有效的内容备份 JSON。'; } finally { backupBusy = ''; if (importInput) importInput.value = ''; } }
  onMount(() => { const query = new URLSearchParams(window.location.search); const requested = query.get('view'); if (requested && navigation.some((item) => item.id === requested)) view = requested as View; loadWorkspace(true, true); const unsubscribe = client.onAuthChange(handleAuthChange); return unsubscribe; });
</script>

<div class="cms-shell"><header class="topbar"><a class="brand" href="/">{defaults.title}</a><CmsAccount {client} {profile} compact onProfileChange={() => handleAuthChange()} /></header><div class="layout"><nav aria-label="后台导航" class="sidebar"><div class="nav-links">{#each visibleNav as item}<button type="button" class:active={view === item.id} on:click={() => setView(item.id)}>{item.label}</button>{/each}</div><a class="comment-link" href="/moderation/">评论审核 ↗</a></nav><main>
  {#if error}<p class="global error" role="alert">{error}</p>{/if}{#if authChangeGuard}<p class="global error" role="alert">登录状态已变化。未保存的编辑内容仍留在当前页面；请先导出或保存文本，再刷新页面。</p>{/if}{#if message}<p class="global success" role="status">{message}</p>{/if}
  {#if loading}<section class="loading"><h1>正在连接内容后台…</h1><p>会在登录状态确认后读取可访问的数据。</p></section>
  {:else if !profile}<section class="welcome"><p class="eyebrow">内容后台</p><h1>登录后管理你的内容</h1><p>使用 GitHub 登录。首次登录会自动登记为普通成员；只有 owner、admin 或 editor 可以写作和发布。</p><CmsAccount {client} {profile} onProfileChange={() => handleAuthChange()} /></section>
  {:else if !profile.active}<section class="welcome"><h1>账户已停用</h1><p>此 GitHub 账户当前没有后台访问权限，请联系站长处理。</p><CmsAccount {client} {profile} onProfileChange={() => handleAuthChange()} /></section>
  {:else if view === 'overview'}<section class="overview"><p class="eyebrow">欢迎回来，{profile.display_name || profile.login}</p><h1>内容总览</h1><div class="cards"><button type="button" on:click={() => setView('content')}><strong>{documents.length}</strong><span>全部内容</span></button><button type="button" on:click={() => setView('content')}><strong>{currentPublished}</strong><span>已发布</span></button><button type="button" on:click={() => setView('content')}><strong>{currentDrafts}</strong><span>草稿</span></button></div>{#if editable}<div class="quick"><h2>开始写作</h2>{#each Object.entries(cmsKindLabels) as [kind,label]}<button type="button" on:click={() => create(kind as CmsKind)}>新建{label}</button>{/each}</div>{:else}<p class="notice">当前账户是普通成员，没有内容编辑权限；权限由站长分配。</p>{/if}</section>
  {:else if !editable}<section class="welcome"><h1>当前页面需要编辑权限</h1><p>此账户是普通成员，无法访问内容、编辑器、图片库或内容备份。</p></section>
  {:else if !admin && (view === 'settings' || view === 'members' || view === 'audit')}<section class="welcome"><h1>当前页面需要管理权限</h1><p>站点设置、成员管理和审计记录仅对 owner 与 admin 开放。</p></section>
  {:else if view === 'content'}<CmsDocumentList {documents} onOpen={openDocument} onCreate={create} onAction={action} {busyId} />
  {:else if view === 'editor'}<CmsEditor {client} document={selected} requestedKind={newKind} onSaved={upsert} onClose={() => { editorDirty = false; setView('content'); }} onDirtyChange={(dirty) => editorDirty = dirty} authStale={authChangeGuard} />
  {:else if view === 'media'}<CmsMediaLibrary {client} />
  {:else if view === 'settings'}<SettingsPanel {client} {defaults} onDirtyChange={(dirty) => settingsDirty = dirty} />
  {:else if view === 'members'}<CmsMembers {client} profile={profile} />
  {:else if view === 'audit'}<section class="panel"><h1>审计记录</h1><p>显示最近 100 条受权限保护的后台操作记录。</p>{#if auditLoading}<p>正在读取审计记录…</p>{:else if auditEntries.length === 0}<p>暂无可显示记录。</p>{:else}<div class="audit-list">{#each auditEntries as entry}<pre>{JSON.stringify(entry, null, 2)}</pre>{/each}</div>{/if}</section>
  {:else if view === 'backup'}<section class="panel"><p class="eyebrow">授权导出与导入</p><h1>内容备份</h1><p>导出当前账户有权读取的真实内容、版本、设置和媒体元数据。媒体二进制文件不包含在此导出中；导入会保留现有内容并跳过重复记录。</p><div class="backup-actions"><button type="button" class="primary" disabled={!!backupBusy} on:click={() => downloadBackup('json')}>{backupBusy === 'json' ? '正在生成…' : '导出 JSON'}</button><button type="button" disabled={!!backupBusy} on:click={() => downloadBackup('markdown')}>{backupBusy === 'markdown' ? '正在生成…' : '导出 Markdown'}</button><label class="import-action">导入 JSON 内容备份<input bind:this={importInput} type="file" accept="application/json,.json" disabled={!!backupBusy} on:change={importBackup} /></label></div></section>{/if}
</main></div></div>

<svelte:window on:beforeunload={(event) => { if (editorDirty || settingsDirty) { event.preventDefault(); event.returnValue = ''; } }} />

<style>
  .cms-shell { max-width:88rem; margin:0 auto; padding:1rem; color:var(--site-text); } .topbar { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:center; gap:.75rem; margin-bottom:1rem; } .brand { color:var(--site-link); font-weight:800; text-decoration:none; } .layout { display:grid; grid-template-columns:12rem minmax(0,1fr); gap:1rem; } .sidebar { position:sticky; top:5.25rem; align-self:start; display:grid; gap:.75rem; padding:.65rem; border:1px solid var(--site-border); border-radius:.65rem; background:var(--site-surface); } .nav-links { display:grid; gap:.2rem; } .nav-links button,.comment-link { display:flex; min-height:44px; align-items:center; border:0; border-radius:.35rem; padding:.45rem .65rem; background:transparent; color:var(--site-text); font:inherit; font-weight:650; text-align:left; text-decoration:none; cursor:pointer; } .nav-links button.active { background:var(--site-tint); color:var(--site-link); } .comment-link { border-top:1px solid var(--site-border); color:var(--site-link); } main { min-width:0; } .global { margin:0 0 1rem; padding:.65rem .8rem; border-left:4px solid currentColor; } .error { color:#b91c1c; background:#fef2f2; } .success { color:#166534; background:#f0fdf4; } .loading,.welcome,.overview,.panel { padding:clamp(1.25rem,4vw,2.4rem); border:1px solid var(--site-border); border-radius:.75rem; background:var(--site-surface); } h1 { margin:.15rem 0 .8rem; color:var(--site-link); font-size:clamp(1.6rem,4vw,2.35rem); } .eyebrow { margin:0; color:var(--site-link); font-weight:750; font-size:.8rem; } .welcome { max-width:48rem; line-height:1.8; } .cards { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:.8rem; margin:1.25rem 0; } .cards button,.quick button,.backup-actions button,.import-action { min-height:44px; border:1px solid var(--site-border); border-radius:.5rem; padding:1rem; background:var(--site-background); color:var(--site-text); font:inherit; cursor:pointer; text-align:left; } .import-action { display:inline-flex; align-items:center; gap:.5rem; } .import-action input { max-width:12rem; } .cards strong,.cards span { display:block; } .cards strong { color:var(--site-link); font-size:1.75rem; } .cards span { margin-top:.25rem; color:var(--site-text-muted); font-size:.85rem; } .quick { display:flex; flex-wrap:wrap; gap:.55rem; align-items:center; padding-top:1rem; border-top:1px solid var(--site-border); } .quick h2 { width:100%; margin:0 0 .2rem; font-size:1.05rem; } .notice { color:var(--site-text-muted); line-height:1.7; } .audit-list { display:grid; gap:.75rem; max-height:38rem; overflow:auto; } pre { margin:0; padding:.75rem; border:1px solid var(--site-border); border-radius:.4rem; background:var(--site-background); white-space:pre-wrap; overflow-wrap:anywhere; font-size:.8rem; } .backup-actions { display:flex; flex-wrap:wrap; gap:.65rem; margin-top:1rem; } .primary { background:var(--site-tint) !important; color:var(--site-link) !important; font-weight:750 !important; } button:disabled,input:disabled { opacity:.55; cursor:wait; } button:focus-visible,a:focus-visible,input:focus-visible { outline:3px solid var(--site-accent); outline-offset:3px; } @media(max-width:780px){.layout{grid-template-columns:1fr}.sidebar{position:static;grid-template-columns:1fr}.nav-links{display:flex;overflow-x:auto}.nav-links button{white-space:nowrap}.comment-link{border-top:0;border-left:1px solid var(--site-border)}.cards{grid-template-columns:1fr}.topbar :global(.account){width:100%;}}
</style>
